/* eslint-disable ts/method-signature-style */

declare global {
  interface Uint8Array {
    toHex(): string
  }
  interface Uint8ArrayConstructor {
    fromHex(string: string, into?: Uint8Array): { bytes: Uint8Array; read: number }
  }
}

if (!("toHex" in Uint8Array.prototype)) {
  ;(Uint8Array.prototype as Uint8Array<ArrayBuffer>).toHex = function () {
    let result = ""
    for (const byte of this) {
      result += byte.toString(16).padStart(2, "0")
    }
    return result
  }
}

const NOT_HEX = /[^\da-f]/i
if (!("fromHex" in Uint8Array)) {
  ;(Uint8Array as Uint8ArrayConstructor).fromHex = function (
    string: string,
    into?: Uint8Array,
  ) {
    const stringLength = string.length
    if (stringLength % 2 !== 0) {
      throw new SyntaxError("String should be an even number of characters")
    }

    const maxLength = into ? Math.min(into.length, stringLength / 2) : stringLength / 2
    const bytes = into ?? new Uint8Array(maxLength)
    let read = 0
    let written = 0
    while (written < maxLength) {
      const hexits = string.slice(read, (read += 2))
      if (NOT_HEX.exec(hexits)) {
        throw new SyntaxError("String should only contain hex characters")
      }
      bytes[written++] = Number.parseInt(hexits, 16)
    }
    return { bytes, read }
  }
}

export {}
